const FLOWERS = {
  poppy: [200, 30, 30], dandelion: [240, 220, 40], blue_orchid: [40, 160, 220], allium: [180, 110, 220], azure_bluet: [220, 230, 230],
  red_tulip: [210, 50, 40], orange_tulip: [230, 120, 30], white_tulip: [230, 230, 220], pink_tulip: [230, 160, 200],
  oxeye_daisy: [230, 230, 210], cornflower: [70, 100, 220], lily_of_the_valley: [235, 235, 235], wither_rose: [40, 40, 30],
  sunflower: [245, 200, 30], lilac: [200, 140, 200], rose_bush: [200, 40, 40], peony: [230, 170, 220], torchflower: [230, 150, 60],
  pink_petals: [240, 170, 200], wildflowers: [240, 220, 90], spore_blossom: [210, 110, 160],
};

function hashColor(name) {
  let h = 2166136261;
  for (let i = 0; i < name.length; i++) { h ^= name.charCodeAt(i); h = Math.imul(h, 16777619); }
  const r = 90 + ((h >>> 0) % 110), g = 90 + ((h >>> 8) % 110), b = 90 + ((h >>> 16) % 110);
  return [r, g, b];
}

const SUFFIXES = ['_stairs', '_slab', '_wall', '_fence_gate', '_fence', '_pressure_plate', '_button', '_trapdoor', '_door',
  '_wall_hanging_sign', '_hanging_sign', '_wall_sign', '_sign', '_pane'];

function baseCandidates(stem) {
  const c = [stem, `${stem}s`, `${stem}_block`, `${stem}_planks`, stem.replace(/brick$/, 'bricks'), stem.replace(/tile$/, 'tiles')];
  if (stem.endsWith('_brick')) c.push(`${stem}s`);
  if (stem === 'quartz' || stem === 'smooth_quartz') c.push('quartz_block');
  if (stem === 'purpur') c.push('purpur_block');
  if (stem === 'petrified_oak') c.push('oak_planks');
  return c;
}

function lookup(name) {
  if (TABLE[name]) {
    const t = TABLE[name];
    return { top: t.top, side: t.side ?? t.top, a: t.a ?? 1 };
  }
  if (BASE[name]) {
    const [top, side, a] = BASE[name];
    return { top, side: side ?? top, a: a ?? 1 };
  }
  return null;
}

function resolveColor(name) {
  const direct = lookup(name);
  if (direct) return direct;
  if (FLOWERS[name]) return { top: FLOWERS[name], side: FLOWERS[name], a: 1 };
  const potted = /^potted_(.+)$/.exec(name);
  if (potted) return resolveColor(potted[1]);
  // wood
  for (const [w, c] of Object.entries(WOOD)) {
    if (name === `${w}_planks` || name === `stripped_${w}_log` || name === `stripped_${w}_wood` || name === `stripped_${w}_stem` || name === `stripped_${w}_hyphae`) {
      return { top: c.planks, side: c.planks, a: 1 };
    }
    if (name === `${w}_log` || name === `${w}_wood` || name === `${w}_stem` || name === `${w}_hyphae` || name === `${w}_block`) {
      return { top: name.endsWith('_wood') || name.endsWith('_hyphae') ? c.log : c.planks, side: c.log, a: 1 };
    }
    if (name === `${w}_leaves` || name === `${w}_wart_block` || (w === 'crimson' && name === 'nether_wart_block')) return { top: c.leaves, side: c.leaves, a: 1 };
    if (name === `${w}_sapling`) return { top: c.leaves, side: c.leaves, a: 1 };
    if (name.startsWith(`${w}_`) && SUFFIXES.some((s) => name.endsWith(s))) return { top: c.planks, side: c.planks, a: 1 };
  }
  if (name === 'azalea_leaves' || name === 'azalea') return { top: [90, 117, 45], side: [90, 117, 45], a: 1 };
  if (name === 'flowering_azalea_leaves' || name === 'flowering_azalea') return { top: [110, 112, 70], side: [110, 112, 70], a: 1 };
  if (name === 'warped_wart_block') return { top: [22, 119, 121], side: [22, 119, 121], a: 1 };
  // dyed
  const d = DYE_RE.exec(name);
  if (d) {
    const dye = DYES[d[1]], rest = d[2];
    if (rest === 'concrete' || rest === 'concrete_powder') return { top: dye.concrete, side: dye.concrete, a: 1 };
    if (rest === 'terracotta' || rest === 'glazed_terracotta') return { top: dye.terracotta, side: dye.terracotta, a: 1 };
    if (rest === 'stained_glass' || rest === 'stained_glass_pane') return { top: dye.wool, side: dye.wool, a: 0.5 };
    return { top: dye.wool, side: dye.wool, a: 1 }; // wool, carpet, bed, banner, candle, shulker_box…
  }
  if (name === 'moss_carpet') return resolveColor('moss_block');
  if (name === 'pale_moss_carpet') return resolveColor('pale_moss_block');
  if (name === 'glass_pane') return resolveColor('glass');
  // copper variants: waxed_*, cut_*, chiseled_*, *_grate, *_bulb, *_door…
  const copper = /^(waxed_)?(exposed_|weathered_|oxidized_)?(cut_|chiseled_)?copper/.exec(name);
  if (copper) return resolveColor(`${copper[2] ?? ''}copper${copper[2] ? '' : '_block'}`.replace(/^copper$/, 'copper_block'));
  // strip shape suffixes and retry (stone_brick_stairs → stone_bricks)
  for (const s of SUFFIXES) {
    if (name.endsWith(s)) {
      const stem = name.slice(0, -s.length);
      for (const cand of baseCandidates(stem)) {
        const c = lookup(cand);
        if (c) return c;
      }
    }
  }
  if (/_ore$/.test(name)) return { top: name.startsWith('deepslate_') ? [80, 80, 82] : [125, 125, 125], side: [125, 125, 125], a: 1 };
  if (/torch$/.test(name)) return resolveColor('torch');
  if (/glass/.test(name)) return resolveColor('glass');
  if (/coral/.test(name)) return { top: [200, 90, 140], side: [200, 90, 140], a: 1 };
  if (/mushroom/.test(name)) return { top: /red/.test(name) ? [200, 46, 45] : [149, 111, 81], side: [200, 190, 170], a: 1 };
  const h = hashColor(name);
  return { top: h, side: h, a: 1 };
}

const CROSS_RE = /(sapling|_flower$|tulip|^poppy$|^dandelion$|^allium$|^azure_bluet$|^oxeye_daisy$|^cornflower$|^lily_of_the_valley$|^wither_rose$|^short_grass$|^tall_grass$|^fern$|^large_fern$|bush$|^wheat$|^carrots$|^potatoes$|^beetroots$|^sugar_cane$|^(brown|red)_mushroom$|_fungus$|_roots$|^sunflower$|^lilac$|^rose_bush$|^peony$|^kelp|seagrass$|^torchflower|_sprouts$|^nether_wart$|^cobweb$|^dead_bush$|^bamboo$|^pitcher_|vine)/;
const POST_RE = /(_fence$|_wall$|chain$|^end_rod$|^lightning_rod$|torch$|^candle$|_candle$|lantern$|^flower_pot$|^potted_|^bell$|^ladder$|_sign$|_banner$|^lever$|_button$|^tripwire_hook$|^scaffolding$|_head$|_skull$)/;
const THIN_RE = /(carpet$|pressure_plate$|rail$|^redstone_wire$|^repeater$|^comparator$|^lily_pad$|^pink_petals$|^wildflowers$|^leaf_litter$|^snow$|^tripwire$|_trapdoor$)/;

/**
 * @returns {{ top:number[], side:number[], a:number, shape:string, props:object, name:string }}
 */
const cache = new Map();
export function blockColor(block) {
  let r = cache.get(block);
  if (r) return r;
  const b = parseBlock(block);
  const name = b.name;
  let c = resolveColor(name);
  let shape = 'cube';
  if (/_slab$/.test(name)) shape = b.props.type === 'top' ? 'slab-top' : b.props.type === 'double' ? 'cube' : 'slab-bottom';
  else if (/_stairs$/.test(name)) shape = 'stairs';
  else if (/_trapdoor$/.test(name)) shape = b.props.open === 'true' ? 'cube-thin' : b.props.half === 'top' ? 'slab-top-thin' : 'thin';
  else if (/door$/.test(name)) {
    shape = 'door';
    c = { ...c, top: c.top.map((v) => v * 0.72), side: c.side.map((v) => v * 0.72) };
  } else if (/_pane$|^iron_bars$/.test(name)) {
    shape = 'pane';
    c = { ...c, a: Math.min(c.a, name === 'iron_bars' ? 0.55 : 0.4) };
  } else if (name === 'snow') shape = Number(b.props.layers ?? 1) >= 8 ? 'cube' : 'thin';
  else if (THIN_RE.test(name)) shape = 'thin';
  else if (POST_RE.test(name)) shape = 'post';
  else if (CROSS_RE.test(name)) shape = 'cross';
  else if (/_bed$/.test(name)) shape = 'slab-bottom';
  r = { ...c, shape, props: b.props, name };
  cache.set(block, r);
  return r;
}

/** True when a block fully hides what's behind it (used for face culling). */
export function isOpaqueCube(block) {
  const c = blockColor(block);
  return c.shape === 'cube' && c.a >= 1;
}
